#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=9
ACCOUNT="${1:-}"
REPO_ROOT="/c/code/v1be-infra"
WORK="/c/v1be-work/accounts-$ACCOUNT"
STACK="$WORK/stacks/accounts"
# The backend reads state in the management account, and the provider works in
# the member account through its own profile. One SSO sign-in covers both.
export AWS_PROFILE="v1be-admin"
MEMBER_PROFILE="v1be-admin-$ACCOUNT"
# Stops Git Bash rewriting the slashes in the ARN passed to terraform import.
export MSYS_NO_PATHCONV=1

# The accounts stack runs only in Windows Sandbox (ADR-0012).
if [[ ! -d "$REPO_ROOT/sandbox" ]]; then
  warn "Stopping: this isn't Windows Sandbox. Open v1be-admin.wsb and run it there."
  exit 1
fi

case "$ACCOUNT" in
  portfolio) ACCOUNT_NAME="portfolio" ;;
  cafe) ACCOUNT_NAME="collective-cafe-prod" ;;
  *)
    warn "Usage: accounts-apply.sh portfolio, or accounts-apply.sh cafe"
    exit 1
    ;;
esac

banner "Terraform: accounts stack, $ACCOUNT_NAME"

stage "Before you start"
say "This signs in, shows you the plan, and applies it only if you say yes."
note "Read stacks/accounts and modules first."
note "If this Sandbox is new, run identity-center.sh first so the AWS CLI is set up."
note "Run portfolio first, then cafe. State is in S3, so closing the Sandbox loses nothing."
pause

stage "Sign in as v1be-admin"
if ! aws configure get sso_session --profile "$AWS_PROFILE" >/dev/null 2>&1 \
  && ! aws configure get sso_start_url --profile "$AWS_PROFILE" >/dev/null 2>&1; then
  warn "Stopping: this Sandbox has no $AWS_PROFILE profile. Run identity-center.sh, then come back."
  exit 1
fi
if aws sts get-caller-identity --profile "$AWS_PROFILE" >/dev/null 2>&1; then
  say "Already signed in to AWS."
else
  step "A browser opens. Sign in and allow the request."
  aws sso login --profile "$AWS_PROFILE"
fi
CALLER_ACCOUNT="$(aws sts get-caller-identity --query Account --output text | tr -d '\r')"
MANAGEMENT_ACCOUNT="$(aws organizations describe-organization --query Organization.MasterAccountId --output text | tr -d '\r')"
if [[ -z "$CALLER_ACCOUNT" || "$CALLER_ACCOUNT" != "$MANAGEMENT_ACCOUNT" ]]; then
  warn "Stopping: this login isn't in the management account."
  exit 1
fi
say "PASS: signed in to the management account"
pause

stage "Set up the member account's profile"
ACCOUNT_ID="$(aws organizations list-accounts --query "Accounts[?Name=='$ACCOUNT_NAME'].Id | [0]" --output text | tr -d '\r')"
if [[ ! "$ACCOUNT_ID" =~ ^[0-9]{12}$ ]]; then
  warn "Stopping: no account is named $ACCOUNT_NAME."
  exit 1
fi
for key in sso_session sso_start_url sso_region region; do
  value="$(aws configure get "$key" --profile "$AWS_PROFILE" 2>/dev/null | tr -d '\r' || true)"
  if [[ -n "$value" ]]; then
    aws configure set "$key" "$value" --profile "$MEMBER_PROFILE"
  fi
done
aws configure set sso_account_id "$ACCOUNT_ID" --profile "$MEMBER_PROFILE"
aws configure set sso_role_name AdministratorAccess --profile "$MEMBER_PROFILE"
MEMBER_CALLER="$(aws sts get-caller-identity --profile "$MEMBER_PROFILE" --query Account --output text | tr -d '\r')"
if [[ "$MEMBER_CALLER" != "$ACCOUNT_ID" ]]; then
  warn "Stopping: profile $MEMBER_PROFILE didn't reach $ACCOUNT_NAME."
  exit 1
fi
say "PASS: profile $MEMBER_PROFILE reaches $ACCOUNT_NAME"
pause

stage "Copy the stack and initialise"
note "The code folder is read-only here, so Terraform works in $STACK."
note "The modules go with it, because the stack finds them by relative path."
mkdir -p "$WORK"
rm -rf "$WORK/stacks" "$WORK/modules"
mkdir -p "$WORK/stacks"
cp -r "$REPO_ROOT/stacks/accounts" "$WORK/stacks/"
cp -r "$REPO_ROOT/modules" "$WORK/"
cd "$STACK"
terraform init -input=false -lockfile=readonly -backend-config="key=accounts/$ACCOUNT/terraform.tfstate"
pause

stage "Set the run's values"
step "Enter your plain Gmail address, with no + tag. Cost alerts and episode alarms go there."
ask ROOT_EMAIL "Mailbox"
export TF_VAR_root_email="$ROOT_EMAIL"
export TF_VAR_account="$ACCOUNT"
export TF_VAR_account_id="$ACCOUNT_ID"
export TF_VAR_aws_profile="$MEMBER_PROFILE"
pause

stage "Import a default cost monitor, if AWS made one"
note "An account can have one monitor of this type, so Terraform takes over any that exists."
MONITOR="aws_ce_anomaly_monitor.services"
if terraform state show "$MONITOR" >/dev/null 2>&1; then
  say "Already in state."
else
  if ! MONITOR_ARN="$(aws ce get-anomaly-monitors --profile "$MEMBER_PROFILE" \
    --query "AnomalyMonitors[?MonitorDimension=='SERVICE'].MonitorArn | [0]" --output text)"; then
    warn "Stopping: AWS wouldn't list cost monitors. Nothing was changed. Tell Claude the error, without any account IDs."
    exit 1
  fi
  MONITOR_ARN="$(printf '%s' "$MONITOR_ARN" | tr -d '\r')"
  if [[ -z "$MONITOR_ARN" || "$MONITOR_ARN" == "None" ]]; then
    say "No monitor exists, so Terraform will create one."
  else
    terraform import -input=false "$MONITOR" "$MONITOR_ARN"
  fi
fi
pause

stage "Read the plan"
if ! terraform plan -input=false -no-color -out=tfplan | tee plan.txt; then
  warn "Stopping: the plan failed. Tell Claude the error, without any account IDs."
  exit 1
fi
printf '\n'
NO_CHANGES=0
grep -q '^No changes\.' plan.txt && NO_CHANGES=1
if (( ! NO_CHANGES )) && ! grep -qE '^Plan: .*, 0 to destroy\.$' plan.txt; then
  warn "Stopping: this plan would destroy something. Nothing was changed. Tell Claude the Plan line."
  exit 1
fi
if (( ! NO_CHANGES )) && grep -q 'must be replaced' plan.txt; then
  warn "Stopping: this plan would replace something. Nothing was changed. Tell Claude what."
  exit 1
fi
grep -E '^(Plan:|No changes\.)' plan.txt
step "Scroll up and read what will change."
pause

stage "Apply"
if (( NO_CHANGES )); then
  say "Nothing to apply."
else
  if ! confirm "Does the plan look right, and should Terraform apply it?"; then
    warn "Stopping. Nothing was changed. Tell Claude what looked wrong."
    exit 1
  fi
  terraform apply -input=false tfplan
fi
pause

stage "Confirm the alarm email"
TOPIC_ARN="arn:aws:sns:ap-southeast-1:$ACCOUNT_ID:v1be-alerts"
PENDING="$(aws sns list-subscriptions-by-topic --topic-arn "$TOPIC_ARN" --profile "$MEMBER_PROFILE" \
  --query "length(Subscriptions[?SubscriptionArn=='PendingConfirmation'])" --output text | tr -d '\r')"
if [[ "$PENDING" == "0" ]]; then
  say "PASS: the alarm email is already confirmed"
else
  say "AWS has emailed $ROOT_EMAIL, subject \"AWS Notification - Subscription Confirmation\"."
  warn "Don't click its link. Clicking would let anyone you forward an alarm to unsubscribe you."
  step "In Gmail, right-click \"Confirm subscription\" and copy the link address."
  step "Paste it below with a right-click."
  CONFIRMED=0
  for _ in 1 2 3; do
    ask CONFIRM_URL "Link" || break
    TOKEN="$(printf '%s' "$CONFIRM_URL" | sed -n 's/.*[?&]Token=\([^&]*\).*/\1/p')"
    if [[ -z "$TOKEN" ]]; then
      warn "That link has no Token. Copy the whole link and try again."
      continue
    fi
    if aws sns confirm-subscription --topic-arn "$TOPIC_ARN" --token "$TOKEN" \
      --authenticate-on-unsubscribe true --profile "$MEMBER_PROFILE" >/dev/null; then
      CONFIRMED=1
      break
    fi
    warn "AWS refused that link. Check it's the newest email for $ACCOUNT_NAME, and try again."
  done
  unset CONFIRM_URL TOKEN
  if (( ! CONFIRMED )); then
    warn "FAIL: the alarm email isn't confirmed. Run this wizard again to retry."
    exit 1
  fi
  say "PASS: the alarm email is confirmed, and only a signed-in admin can unsubscribe it"
fi
pause

stage "Last check"
PLAN_RC=0
terraform plan -input=false -no-color -detailed-exitcode >second-plan.txt 2>&1 || PLAN_RC=$?
rm -f tfplan plan.txt
if (( PLAN_RC == 1 )); then
  warn "FAIL: the second plan hit an error. Nothing was changed. It says:"
  grep -E '^(│ )?Error:' second-plan.txt || true
  warn "Tell Claude that line, without any account IDs."
  rm -f second-plan.txt
  exit 1
fi
if (( PLAN_RC == 2 )); then
  warn "FAIL: the second plan wants more changes. Nothing was changed. It lists:"
  grep -E '^  # |^      [~+-] |^Plan:' second-plan.txt | grep -v -E '@|id += |[0-9]{12}' || true
  warn "Tell Claude those lines, without any account IDs."
  rm -f second-plan.txt
  exit 1
fi
rm -f second-plan.txt
say "PASS: a second plan shows no changes"
pause

finish
say "Tell Claude the check passed, and what the Plan line said."
note "Don't share account IDs."
}

run_wizard "$@"; exit
